import {INITIAL,sum,detected,blank,newRound,status,rows,recent,quantities,parsePaper} from './core.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='giro-supporti-v1';
class LocalRepository{load(){try{return JSON.parse(localStorage.getItem(KEY))||{sequence:structuredClone(INITIAL),rounds:[],active:null};}catch{throw Error('Impossibile leggere i dati locali. Non sono stati sovrascritti.');}}save(value){localStorage.setItem(KEY,JSON.stringify(value));}}
const repository=new LocalRepository();let db;try{db=repository.load();}catch(e){document.body.textContent=e.message;throw e;}let page='home',r=null,detailMP=null,returnPage='summary',meta={},scanMode='kanban',scanValues=[],paperRows=[],ocrBusy=false,scanTarget=null,scanReturn=null;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000);}
function save(edit=false){if(edit&&r?.end)r.modified=new Date().toISOString();try{repository.save(db);document.querySelectorAll('.saved').forEach(e=>e.textContent='✓ Salvato sul dispositivo');return true;}catch(e){toast('Salvataggio non riuscito: memoria del dispositivo piena o non disponibile.');document.querySelectorAll('.saved').forEach(e=>e.textContent='⚠ Dati non salvati');return false;}}
const fmt=(t,options={})=>new Date(t).toLocaleString('it-IT',options);const endLabel=r=>r.end?fmt(r.end,{day:'2-digit',month:'long',hour:'2-digit',minute:'2-digit'}):'Giro in corso';
function nav(p){page=p;render();window.scrollTo(0,0);}
function dialog(title,text,confirm){$('#modal').innerHTML=`<div class="modal-scroll"><h2>${title}</h2><p>${esc(text)}</p></div><div class="row modal-actions"><button id="cancel">Annulla</button><button class="primary" id="yes">Conferma</button></div>`;$('#modal').showModal();$('#cancel').onclick=()=>$('#modal').close();$('#yes').onclick=()=>{$('#modal').close();confirm();};}
function base(body,dock=''){ $('#app').innerHTML=`<header><div class="brand"><img src="./icon.svg" alt="">GIRO SUPPORTI</div></header><main>${page!=='home'?'<button class="small" data-action="back">← Indietro</button>':''}${body}</main>${dock?`<footer class="dock"><div class="row">${dock}</div></footer>`:''}`;}
function heading(k,t,sub=''){return `<p class="eyebrow">${k}</p><h1>${t}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}`;}
function roundButton(x){return `<button class="list-button" data-action="open" data-id="${x.id}"><span>${endLabel(x)}<small>${esc(x.shift)} · ${esc(x.type)}${x.modified?' · Modificato':''}</small></span><span>→</span></button>`;}
function flags(d){return `<div class="row"><button class="flag ${d.flag==='MC'?'selected':''}" data-action="flag" data-value="MC">MC</button><button class="flag ${d.flag==='MS'?'selected':''}" data-action="flag" data-value="MS">MS</button><button class="small ${d.stopped?'selected':''}" data-action="stopped">FERMA</button></div><p class="muted">MC: manca ciclo · MS: mancanza supporti</p><label class="label" for="note">Nota MP (facoltativa)</label><textarea id="note" rows="2" placeholder="Scrivi una nota…">${esc(d.note)}</textarea><p class="saved">✓ Salvato sul dispositivo</p>`;}
function pallets(d){return d.pallets.map((p,i)=>`<div class="card"><div class="row spread"><span class="eyebrow">Pedana ${i+1}</span><strong>${sum(p.expression)}</strong></div><p>${esc(p.expression)}${p.expression.includes('+')?' = '+sum(p.expression):''}</p><div class="row"><button class="small" data-action="edit-pallet" data-index="${i}">Modifica</button><button class="small danger" data-action="delete-pallet" data-index="${i}">Elimina</button></div></div>`).join('');}
function entry(d,type){return type==='B'?`<label class="label" for="b">Quantità residua reale</label><input id="b" class="quantity" type="text" inputmode="numeric" pattern="[0-9]*" placeholder="—" value="${d.b??''}"><button class="zero-button wide" data-action="zero-b" style="margin-top:10px">Conferma 0 pezzi</button><p class="muted">Inserisci il residuo reale, non la quantità stampata.</p>`:`<button class="primary wide" data-action="scan">▣ &nbsp; SCANSIONA PEDANA</button><button class="wide" style="margin-top:10px" data-action="manual">INSERISCI MANUALMENTE</button>${!d.pallets.length?'<button class="zero-button wide" style="margin-top:10px" data-action="zero-k">Conferma 0 pezzi</button>':''}${pallets(d)}${d.pallets.length?'<button class="wide" data-action="manual">+ Aggiungi pedana</button>':''}<div class="card row spread"><span>Totale Kanban</span><span class="total">${d.pallets.reduce((a,p)=>a+sum(p.expression),0)}</span></div>`;}
function render(){
if(page==='home'){let closed=db.rounds.filter(x=>x.end).sort((a,b)=>new Date(b.end)-new Date(a.end));let active=db.rounds.find(x=>x.id===db.active);base(`<h1>Giro supporti</h1><p class="home-clock" id="home-clock"></p><div class="row spread"><span class="pill tag">● ${navigator.onLine?'Dati locali':'Offline'}</span><span class="muted">${db.sequence.filter(s=>s.enabled).length} tappe nel giro</span></div><button class="primary wide start" data-action="${active?'resume':'new'}"><span>${active?'Riprendi giro':'Nuovo giro'}<small>${active?'I tuoi dati sono già salvati':'Inizia il controllo delle presse'}</small></span><span class="arrow">→</span></button>${active?'<button class="wide small danger" data-action="cancel-round">Annulla giro in corso</button>':''}<div class="card"><h2>Ultimo giro</h2>${closed[0]?roundButton(closed[0]):'<p class="muted">Nessun giro chiuso. Il primo lo trovi qui.</p>'}</div><button class="list-button" data-action="history"><span>Storico ultimi 7 giorni<small>Rivedi e modifica i giri chiusi</small></span><span>→</span></button><button class="list-button" data-action="settings"><span>Impostazioni<small>MP, categorie e ordine delle tappe</small></span><span>→</span></button><button class="list-button" data-action="import"><span>Importa giro da foglio<small>Fotografa, verifica e conferma</small></span><span>＋</span></button>`);}
if(page==='confirm'){base(`${heading('Nuovo giro','Prima di partire')}<div class="card"><div class="date-line"><span class="muted">Data</span><br>${fmt(new Date(),{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><div class="date-line"><span class="muted">Ora</span><br>${fmt(new Date(),{hour:'2-digit',minute:'2-digit'})}</div><label class="label">Turno rilevato</label><select id="shift">${['Mattino','Pomeriggio','Notte'].map(s=>`<option ${meta.shift===s?'selected':''}>${s}</option>`).join('')}</select><p class="muted">Mattino 06–14 · Pomeriggio 14–22 · Notte 22–06</p><label class="label">Tipo giro ${meta.outside?'da scegliere':'rilevato'}</label><select id="type">${meta.outside?'<option value="">Scegli il tipo giro</option>':''}${['Inizio turno','Fine turno'].map(s=>`<option ${!meta.outside&&meta.type===s?'selected':''}>${s}</option>`).join('')}</select>${meta.outside?'<p class="muted">Orario fuori dalle finestre di inizio e fine turno.</p>':''}</div><p class="muted">Nel giro salvato conteranno solo data e ora di chiusura.</p>`, '<button class="primary wide" data-action="start">Inizia giro →</button>');}
if(page==='step'){let s=r.steps[r.index],d=r.data[s.mp];base(`<div class="stage-label ${s.type==='K'?'stage-kanban':'stage-bm'}">${s.type==='K'?'KANBAN':'B.M. · BORDO MACCHINA'}</div><h1 class="mp-title">MP ${esc(s.mp)}</h1><div class="row spread"><span class="pill">${r.index+1} di ${r.steps.length}</span><button class="small" data-action="index">☷ Indice giro</button></div><div class="progress"><div style="width:${(r.index+1)/r.steps.length*100}%"></div></div>${s.status==='skipped'?'<p class="note">Tappa saltata. Inserendo una quantità viene riattivata.</p>':''}${entry(d,s.type)}<div class="separator"></div>${flags(d)}<button class="wide small" data-action="skip">Saltata · salta questa tappa</button><button class="wide small danger" style="margin-top:16px" data-action="cancel-round">Annulla giro</button>`, `<button data-action="prev" ${r.index===0?'disabled':''}>← Indietro</button><button class="primary" data-action="next">Fine</button>`);if(s.type==='B')setTimeout(()=>$('#b')?.focus({preventScroll:true}),50);}
if(page==='index'||page==='check'){let missing=r.steps.filter(s=>status(r,s)==='Da fare');base(`${heading(page==='check'?'Controllo finale':'Navigazione',page==='check'?'Controlla il giro':'Indice del giro')}<p class="${missing.length?'note':'muted'}">${missing.length?missing.length+' tappe ancora da compilare. Puoi correggerle o segnarle come saltate.':'Tutte le tappe sono compilate o saltate.'}</p>${r.steps.map((s,i)=>`<button class="list-button" data-action="jump" data-index="${i}"><span>${i+1}. ${s.type==='K'?'Kanban':'Bordo macchina'} · MP ${esc(s.mp)}</span><span class="pill ${status(r,s)==='Compilata'?'tag':''}">${status(r,s)}</span></button>`).join('')}`,page==='check'?'<button class="primary wide" data-action="close">CHIUDI GIRO</button>':'');}
if(page==='summary'){base(`${heading('Riepilogo giro',endLabel(r))}<p class="muted">${esc(r.shift)} · ${esc(r.type)}</p>${r.modified?`<p class="note">Modificato il ${fmt(r.modified)}</p>`:''}<p class="muted">Tocca una MP per vedere o modificare i dati.</p><div class="card table-wrap" style="padding:8px"><table><thead><tr><th>MP</th><th>Bordo<br>macchina</th><th>Kanban</th><th>Note</th></tr></thead><tbody>${rows(r).map(d=>`<tr tabindex="0" role="button" data-action="detail" data-mp="${esc(d.mp)}"><td>${esc(d.mp)}</td><td>${d.b??'—'}</td><td>${d.pallets.length?d.pallets.map(p=>sum(p.expression)).join('+'):'—'}</td><td>${esc([d.flag,d.stopped?'FERMA':'',d.note].filter(Boolean).join(' · '))}${r.steps.filter(s=>s.mp===d.mp&&s.status==='skipped').length?'<br><small class="muted">Tappe saltate: '+r.steps.filter(s=>s.mp===d.mp&&s.status==='skipped').map(s=>s.type).join(', ')+'</small>':''}</td></tr>`).join('')}</tbody></table></div><button class="wide danger" data-action="delete-round">Cancella giro</button>`);}
if(page==='detail'){let d=r.data[detailMP];base(`${heading('Dettaglio completo','MP '+esc(detailMP))}${entry(d,'B')}<div class="separator"></div><h2>Kanban</h2>${entry(d,'K')}${flags(d)}`, '<button class="primary wide" data-action="done-detail">Torna al riepilogo</button>');}
if(page==='history'){let rs=recent(db.rounds);base(`${heading('Archivio locale','Ultimi 7 giorni')}<p class="muted">Dal ${fmt(new Date(new Date().setDate(new Date().getDate()-6)),{day:'numeric',month:'long'})} a oggi. Ogni giro è modificabile.</p>${rs.length?rs.map(roundButton).join(''):'<div class="empty">Nessun giro negli ultimi 7 giorni.</div>'}`);}
if(page==='settings'){base(`${heading('Impostazioni','Sequenza del giro')}<p class="muted">Le ripetizioni vengono mantenute. Le modifiche valgono dal prossimo giro.</p>${db.sequence.map((s,i)=>`<div class="settings-row"><div class="row"><label>MP<input inputmode="numeric" value="${esc(s.mp)}" data-setting="mp" data-index="${i}"></label><label>Tappa<select data-setting="type" data-index="${i}"><option ${s.type==='K'?'selected':''}>K</option><option ${s.type==='B'?'selected':''}>B</option></select></label><label>Categoria<select data-setting="category" data-index="${i}">${['AUTO','MOTO','RACING'].map(c=>`<option ${s.category===c?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="row" style="margin-top:12px"><label class="row"><input type="checkbox" ${s.enabled?'checked':''} data-setting="enabled" data-index="${i}">Nel giro</label><button class="small" data-action="up" data-index="${i}" ${i===0?'disabled':''}>↑</button><button class="small" data-action="down" data-index="${i}" ${i===db.sequence.length-1?'disabled':''}>↓</button><button class="small danger" data-action="remove" data-index="${i}">Elimina</button></div></div>`).join('')}<button class="primary wide" data-action="add-step">+ Aggiungi MP / tappa</button><p class="saved">✓ Salvato sul dispositivo</p>`);}
if(page==='scan'){base(`${heading('Verifica lettura','Controlla le quantità')}<p class="note">Conferma ogni valore confrontandolo con il foglio. Eventuali correzioni a penna possono sfuggire all’OCR: nessun valore viene accettato automaticamente.</p><div class="scan-values">${scanValues.map((v,i)=>`<div class="row"><label>Quantità ${i+1}<input inputmode="numeric" data-scan="${i}" value="${esc(v)}"></label><button class="small danger" data-action="remove-scan" data-index="${i}">Elimina</button></div>`).join('')}</div><button class="wide" data-action="add-scan">+ Aggiungi quantità</button><div class="card">Composizione: <strong id="scan-formula">${esc(scanValues.join('+'))}</strong><p>Totale pedana: <strong id="scan-total">${safeSum(scanValues.join('+'))}</strong></p></div>`, '<button class="primary wide" data-action="confirm-scan">Conferma pedana</button>');}
if(page==='import'){base(`${heading('Da foglio cartaceo','Importa un giro')}<p class="muted">Tabella: MP | Bordo macchina | Kanban | Note</p><p class="note">La lettura della scrittura a penna è incerta. Verifica e correggi tutte le righe prima di salvare. La foto non viene conservata.</p><button class="primary wide" data-action="paper-photo">▣ Fotografa foglio</button><label class="label">Data e ora fine giro</label><input type="datetime-local" id="paper-date" value="${meta.paperDate||localDate(new Date())}"><label class="label">Turno</label><select id="paper-shift">${['Mattino','Pomeriggio','Notte'].map(s=>`<option ${meta.paperShift===s?'selected':''}>${s}</option>`).join('')}</select><label class="label">Tipo giro</label><select id="paper-type"><option ${meta.paperType==='Inizio turno'?'selected':''}>Inizio turno</option><option ${meta.paperType==='Fine turno'?'selected':''}>Fine turno</option></select><h3>Righe da verificare</h3>${paperRows.map((v,i)=>`<div class="import-row"><div class="row"><label>MP<input inputmode="numeric" data-paper="mp" data-index="${i}" value="${esc(v.mp)}"></label><label>Bordo macchina<input inputmode="numeric" data-paper="b" data-index="${i}" value="${esc(v.b)}"></label></div><label class="label">Kanban · totali pedane separati da +</label><input inputmode="text" data-paper="k" data-index="${i}" value="${esc(v.k)}"><label class="label">Note (anche MC, MS, FERMA)</label><input data-paper="note" data-index="${i}" value="${esc(v.note)}"><button class="small danger" style="margin-top:10px" data-action="remove-paper" data-index="${i}">Elimina riga</button></div>`).join('')}<button class="wide" data-action="add-paper">+ Aggiungi riga</button><label class="label row"><input style="width:24px;min-height:24px;flex:initial" type="checkbox" id="verified">Ho verificato tutte le righe</label>`, '<button class="primary wide" data-action="save-paper">Conferma e salva giro</button>');}
updateClock();
}
function updateClock(){const clock=$('#home-clock');if(clock){const now=new Date();clock.textContent=fmt(now,{day:'2-digit',month:'2-digit',year:'numeric'})+' · '+fmt(now,{hour:'2-digit',minute:'2-digit'});}}
setInterval(updateClock,1000);document.addEventListener('visibilitychange',updateClock);
function localDate(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}function safeSum(s){try{return sum(s);}catch{return '—';}}function currentMP(){return page==='scan'?scanTarget:page==='detail'?detailMP:r.steps[r.index].mp;}function data(){return r.data[currentMP()];}function reactivate(type){r.steps.filter(s=>s.mp===currentMP()&&s.type===type).forEach(s=>s.status='todo');}
function manual(i=null){
const d=data();let savedIndex=i;
const modal=$('#modal');modal.innerHTML=`<div class="modal-context stage-kanban"><span>KANBAN · Pedana ${i===null?d.pallets.length+1:i+1}</span><strong>MP ${esc(currentMP())}</strong></div><div class="modal-scroll"><h2>${i===null?'Aggiungi':'Modifica'} pedana</h2><label class="label">Composizione</label><input id="expression" inputmode="numeric" enterkeyhint="done" placeholder="750+750" value="${i===null?'':esc(d.pallets[i].expression)}"><button type="button" class="wide small" id="add-quantity" style="margin-top:10px">+ Aggiungi quantità alla pedana</button><p class="muted">Salvataggio automatico. Per zero pezzi usa il pulsante dedicato.</p><p>Totale: <strong id="formula-total">${i===null?'—':sum(d.pallets[i].expression)}</strong></p><p class="saved" id="manual-status"></p></div><div class="row modal-actions"><button class="small" id="manual-more">+ Altra pedana</button><button class="zero-button" id="manual-zero">0 pezzi</button><button class="primary" id="manual-done">Fine</button></div>`;
const field=$('#expression');
function update(){const value=field.value.trim();$('#formula-total').textContent=value===''?'—':safeSum(value);field.setCustomValidity('');if(value===''){if(savedIndex!==null){d.pallets.splice(savedIndex,1);savedIndex=null;save(true);}$('#manual-status').textContent='Nessuna quantità inserita';return;}
try{sum(value);}catch{field.setCustomValidity('Completa la composizione prima di proseguire');$('#manual-status').textContent='Composizione da completare';return;}
if(savedIndex===null){savedIndex=d.pallets.length;d.pallets.push({expression:value});}else d.pallets[savedIndex]={expression:value};reactivate('K');const saved=save(true);$('#manual-status').textContent=saved?'✓ Salvato sul dispositivo':'⚠ Dati non salvati';}
function finish(advance=true){if(!field.checkValidity()){field.reportValidity();return;}if(advance&&field.value.trim()===''){toast('Inserisci una quantità oppure usa 0 pezzi.');return;}if(!save(true))return;modal.close();if(advance&&page==='step')nextStep();else render();}
modal.oncancel=e=>{e.preventDefault();finish(false);};modal.onclose=()=>{modal.oncancel=null;modal.onclose=null;render();};
field.oninput=update;field.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();finish();}};
$('#add-quantity').onclick=()=>{const start=field.selectionStart??field.value.length,end=field.selectionEnd??start;field.value=field.value.slice(0,start)+'+'+field.value.slice(end);update();field.focus();field.setSelectionRange(start+1,start+1);};
$('#manual-more').onclick=()=>{if(!field.checkValidity()){field.reportValidity();return;}if(!field.value.trim()){toast('Inserisci la quantità della pedana prima di aggiungerne un’altra.');return;}if(!save(true))return;savedIndex=null;field.value='';modal.querySelector('.modal-context span').textContent='KANBAN · Pedana '+(d.pallets.length+1);modal.querySelector('h2').textContent='Aggiungi pedana';update();field.focus();};
$('#manual-zero').onclick=()=>{field.value='0';update();finish();};$('#manual-done').onclick=()=>finish();modal.showModal();field.focus();
}
function nextStep(){if($('#b')&&!$('#b').checkValidity()){$('#b').reportValidity();return;}if(status(r,r.steps[r.index])==='Da fare'){toast('Inserisci una quantità oppure segna la tappa come saltata.');return;}if(!save())return;if(r.index===r.steps.length-1)nav('check');else{r.index++;save();nav('step');}}
document.addEventListener('keydown',e=>{if(e.target.id==='b'&&e.key==='Enter'&&page==='step'){e.preventDefault();nextStep();}});
function removeRound(id){const previous=db.rounds,active=db.active;db.rounds=db.rounds.filter(x=>x.id!==id);if(db.active===id)db.active=null;if(save()){r=null;nav('home');}else{db.rounds=previous;db.active=active;}}
function snapshotPaper(){if(page==='import'){meta.paperDate=$('#paper-date').value;meta.paperShift=$('#paper-shift').value;meta.paperType=$('#paper-type').value;}}
function pickPhoto(mode){snapshotPaper();if(mode==='kanban'){scanTarget=currentMP();scanReturn=page;}scanMode=mode;$('#photo').value='';$('#photo').click();}
async function ocr(file){if(ocrBusy)return;ocrBusy=true;let worker;toast('Lecture OCR en cours…'.replace('Lecture OCR en cours…','Lettura OCR in corso…'));try{worker=await Tesseract.createWorker('ita',1,{workerPath:new URL('./vendor/worker.min.js',location.href).href,corePath:new URL('./vendor/core/',location.href).href,langPath:new URL('./vendor/lang/',location.href).href,logger:m=>{if(m.status==='recognizing text'){$('#toast').textContent='Lettura OCR: '+Math.round(m.progress*100)+'%';$('#toast').style.display='block';}}});let result=await worker.recognize(file);let text=result.data.text; if(scanMode==='kanban'){scanValues=quantities(text);if(!scanValues.length){scanValues=[''];toast('Nessuna Qtà leggibile: inserisci i valori manualmente.');}nav('scan');}else{paperRows=parsePaper(text);if(!paperRows.length){paperRows=[{mp:'',b:'',k:'',note:''}];toast('Tabella non leggibile: ricostruisci le righe nella verifica.');}nav('import');}}catch(e){toast('OCR non disponibile. Puoi inserire e verificare i valori manualmente.');if(scanMode==='kanban'){scanValues=[''];nav('scan');}else{if(!paperRows.length)paperRows=[{mp:'',b:'',k:'',note:''}];nav('import');}}finally{if(worker)await worker.terminate();$('#photo').value='';ocrBusy=false;}}
$('#photo').onchange=e=>{const file=e.target.files[0];if(file)ocr(file);};
document.addEventListener('input',e=>{let t=e.target;if(t.id==='b'){if(t.value!==''&&!/^\d+$/.test(t.value)){t.setCustomValidity('Inserisci un numero intero positivo o zero');t.reportValidity();return;}t.setCustomValidity('');data().b=t.value===''?null:Number(t.value);if(t.value!=='')reactivate('B');save(true);}if(t.id==='note'){data().note=t.value;save(true);}if(t.dataset.scan!==undefined){scanValues[Number(t.dataset.scan)]=t.value;$('#scan-formula').textContent=scanValues.join('+');$('#scan-total').textContent=safeSum(scanValues.join('+'));}if(t.dataset.paper){paperRows[+t.dataset.index][t.dataset.paper]=t.value;}if(t.dataset.setting){let s=db.sequence[+t.dataset.index];if(t.dataset.setting==='mp'&&!/^\d+$/.test(t.value)){t.setCustomValidity('Numero MP richiesto');return;}t.setCustomValidity('');s[t.dataset.setting]=t.dataset.setting==='enabled'?t.checked:t.value;save();}});
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,i=+b.dataset.index;switch(a){case 'back':if(page==='step'||page==='check'||page==='summary'||page==='confirm'||page==='settings'||page==='history')nav('home');else if(page==='index')nav('step');else if(page==='detail')nav(returnPage);else if(page==='scan')nav(r.end?'detail':'step');else nav('home');break;case 'cancel-round':{const id=db.active;if(id)dialog('Annullare il giro?','Il giro in corso e i dati inseriti verranno eliminati.',()=>removeRound(id));break;}case 'delete-round':{const id=r.id;dialog('Cancellare il giro?','Questo giro verrà eliminato dallo storico.',()=>removeRound(id));break;}case 'new':if(db.active){toast('Riprendi e chiudi il giro in corso prima di crearne un altro.');break;}if(!db.sequence.some(s=>s.enabled)){toast('Aggiungi almeno una tappa nelle impostazioni.');break;}meta=detected();nav('confirm');break;case 'resume':r=db.rounds.find(x=>x.id===db.active);nav('step');break;case 'start':if(!$('#type').value){toast('Scegli il tipo giro.');break;}r=newRound(db.sequence,{shift:$('#shift').value,type:$('#type').value});db.rounds.push(r);db.active=r.id;save();nav('step');break;case 'prev':r.index=Math.max(0,r.index-1);save();render();break;case 'next':nextStep();break;case 'skip':r.steps[r.index].status='skipped';save();if(r.index<r.steps.length-1){r.index++;save();render();}else nav('check');break;case 'index':nav('index');break;case 'jump':r.index=i;save();nav('step');break;case 'zero-b':data().b=0;reactivate('B');save(true);if($('#b')){$('#b').value='0';$('#b').setCustomValidity('');$('#b').blur();}toast('Bordo macchina: 0 pezzi confermato');break;case 'zero-k':if(!data().pallets.length){data().pallets.push({expression:'0'});reactivate('K');save(true);render();toast('Kanban: 0 pezzi confermato');}break;case 'manual':manual();break;case 'edit-pallet':manual(i);break;case 'delete-pallet':dialog('Elimina pedana','Eliminare questa pedana?',()=>{data().pallets.splice(i,1);save(true);render();});break;case 'flag':data().flag=data().flag===b.dataset.value?'':b.dataset.value;save(true);render();break;case 'stopped':data().stopped=!data().stopped;save(true);render();break;case 'close':if(r.steps.some(s=>status(r,s)==='Da fare')){toast('Compila o segna come saltate le tappe vuote.');break;}dialog('Chiudere il giro?','Verranno salvate data e ora di fine giro.',()=>{r.end=new Date().toISOString();db.active=null;if(save())nav('summary');});break;case 'open':r=db.rounds.find(x=>x.id===b.dataset.id);nav('summary');break;case 'detail':detailMP=b.dataset.mp;returnPage='summary';nav('detail');break;case 'done-detail':nav(returnPage);break;case 'history':nav('history');break;case 'settings':nav('settings');break;case 'up':case 'down':{let j=i+(a==='up'?-1:1);[db.sequence[i],db.sequence[j]]=[db.sequence[j],db.sequence[i]];save();render();break;}case 'remove':dialog('Rimuovi tappa','Rimuovere questa tappa dai prossimi giri?',()=>{db.sequence.splice(i,1);save();render();});break;case 'add-step':db.sequence.push({id:crypto.randomUUID(),mp:'',type:'K',enabled:false,category:'AUTO'});save();render();window.scrollTo(0,document.body.scrollHeight);break;case 'scan':pickPhoto('kanban');break;case 'import':meta={paperDate:localDate(new Date()),paperShift:detected().shift,paperType:detected().type};paperRows=[];nav('import');break;case 'paper-photo':pickPhoto('paper');break;case 'add-scan':scanValues.push('');render();break;case 'remove-scan':scanValues.splice(i,1);render();break;case 'confirm-scan':try{let expression=scanValues.join('+');sum(expression);data().pallets.push({expression});reactivate('K');save(true);nav(scanReturn);}catch(e){toast('Correggi tutte le quantità prima di confermare.');}break;case 'add-paper':snapshotPaper();paperRows.push({mp:'',b:'',k:'',note:''});render();break;case 'remove-paper':snapshotPaper();paperRows.splice(i,1);render();break;case 'save-paper':savePaper();break;}});
function savePaper(){snapshotPaper();if(!$('#verified').checked){toast('Verifica tutte le righe e spunta la conferma.');return;}try{if(!paperRows.length)throw Error('Aggiungi almeno una riga.');if(!meta.paperDate||Number.isNaN(new Date(meta.paperDate).getTime()))throw Error('Data non valida.');if(new Date(meta.paperDate)>new Date())throw Error('La fine giro non può essere nel futuro.');let seen=new Set;for(let v of paperRows){if(!/^\d+$/.test(v.mp))throw Error('Controlla i numeri MP.');if(seen.has(v.mp))throw Error('Ogni MP deve comparire una sola volta nel foglio.');seen.add(v.mp);if(v.b!==''&&!/^\d+$/.test(v.b))throw Error('Controlla Bordo macchina.');if(v.k!=='')sum(v.k);if(v.b===''&&v.k==='')throw Error('Inserisci almeno una quantità per ogni MP.');if(/\bMC\b/i.test(v.note)&&/\bMS\b/i.test(v.note))throw Error('MC e MS sono alternativi: correggi le note.');}let seq=paperRows.flatMap(v=>[{mp:v.mp,type:'K',enabled:true},{mp:v.mp,type:'B',enabled:true}]);r=newRound(seq,{shift:meta.paperShift,type:meta.paperType});r.end=new Date(meta.paperDate).toISOString();for(let v of paperRows){let flag=/\bMC\b/i.test(v.note)?'MC':/\bMS\b/i.test(v.note)?'MS':'';r.data[v.mp]={b:v.b===''?null:Number(v.b),pallets:v.k===''?[]:v.k.split('+').map(n=>({expression:n.trim()})),flag,stopped:/\bFERMA\b/i.test(v.note),note:v.note.replace(/\b(MC|MS|FERMA)\b/gi,'').trim()};r.steps.filter(s=>s.mp===v.mp).forEach(s=>{if(s.type==='B'&&v.b===''||s.type==='K'&&v.k==='')s.status='skipped';});}db.rounds.push(r);if(save())nav('summary');}catch(e){toast(e.message);}}
window.addEventListener('online',()=>{if(page==='home')render();});window.addEventListener('offline',()=>{if(page==='home')render();});window.addEventListener('pagehide',()=>save());
// Android Back changes screen instead of immediately leaving the app.
history.replaceState({giro:true},'');history.pushState({giro:true},'');window.addEventListener('popstate',()=>{if($('#modal').open){if($('#manual-done'))$('#modal').dispatchEvent(new Event('cancel',{cancelable:true}));else $('#modal').close();}else if(page==='detail')nav(returnPage);else if(page==='index'||page==='scan')nav('step');else nav('home');history.pushState({giro:true},'');});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Cache offline non disponibile in questo browser.'));
render();

function fitVisibleViewport(){const viewport=window.visualViewport;const height=viewport?.height||window.innerHeight;const top=viewport?.offsetTop||0;document.documentElement.style.setProperty('--visible-height',height+'px');document.documentElement.style.setProperty('--visible-top',top+'px');document.documentElement.style.setProperty('--keyboard-inset',Math.max(0,window.innerHeight-height-top)+'px');}window.visualViewport?.addEventListener('resize',fitVisibleViewport);window.visualViewport?.addEventListener('scroll',fitVisibleViewport);window.addEventListener('resize',fitVisibleViewport);fitVisibleViewport();
